#### baseIH determina o que é usado para calcular a taxa de IRS (categories['BASIC'] vai englobar tudo o que tenha categoria Vencimento Base (por defeito Vencimento Base e Isenção de Horário | BASIC é apenas a regra com código BASIC - Vencimento Base)
if payslip.payslip_type == 'extraordinary':

    baseIH = get_previous_amount(payslip, 'BASIC')
elif payslip.payslip_type == 'normal':
    baseIH = contract.wage
else:
    baseIH = _get_irs_tax_cease_vac(employee, payslip, contract)
if contract.exemption_schedule:
    baseIH = contract.wage + (contract.wage * contract.exemption_schedule_percentage)
is_chr = False
is_vac = True
is_meal = False
if baseIH > 0:
    result_rate, result = compute_irs_allowances(contract, categories, employee, payslip, is_chr, is_vac, is_meal, baseIH)
else:
    result_rate = 0
    result = 0

