base = 0

previous_slips = payslip.env['hr.payslip'].search([('employee_id', '=', employee.id), ('state', 'in', ['done', 'paid'])], order= 'create_date desc', limit=1)

for slip in previous_slips:
    for line in slip.line_ids.filtered(lambda l: l.category_id.code == 'BASIC'):
        base += line.total
if contract.time_credit:
    worked_hours = 0
    for line in payslip.worked_days_line_ids.filtered(lambda w: w.is_correction):
        worked_hours += line.number_of_hours
    worked_days = int(worked_hours / 6)
    surplus = worked_hours % 6
    if surplus > 3:
        worked_days += 1
    elif surplus <= 3:
        worked_days += 0.5
else:
    worked_days = 0
    for line in payslip.worked_days_line_ids.filtered(lambda w: w.is_correction):
        worked_days += line.number_of_days
result = (base / 30) * worked_days

